// One Slack message per client: the summary, each number against last week, each network and the top posts.
const o = $('Had a week').item.json;
const k = o.kpis || {};
const name = (n) => ({ instagram: 'Instagram', facebook: 'Facebook', tiktok: 'TikTok', threads: 'Threads', youtube: 'YouTube', linkedin: 'LinkedIn' })[n] ?? n;
const n = (v) => (typeof v === 'number' ? Math.round(v).toLocaleString('en-US') : '-');
const change = (x) => {
  if (!x || typeof x.previous !== 'number' || x.previous === 0) return '';
  const pct = Math.round(((x.value - x.previous) / x.previous) * 100);
  return ` (${pct >= 0 ? '+' : ''}${pct}%)`;
};
const f = k.followers;
const count = (v, one, many) => `${n(v)} ${v === 1 ? one : many}`;
const network = (x) => [`${n(x.views)} views`, typeof x.engagements === 'number' ? count(x.engagements, 'engagement', 'engagements') : null,
  typeof x.posts === 'number' ? count(x.posts, 'post', 'posts') : null].filter(Boolean).join(', ');
const lines = [
  `*${$('Get clients').item.json.name}*, ${o.from} to ${o.to}`,
  $json.message.content.trim(),
  '',
  `Views: ${n(k.views?.value)}${change(k.views)}`,
  `Reach: ${n(k.reach?.value)}${change(k.reach)}`,
  `Engagements: ${n(k.engagements?.value)}${change(k.engagements)}`,
  `Posts: ${n(k.posts?.value)}${change(k.posts)}`,
  ...(f ? [`Followers: ${n(f.value)} (${f.change >= 0 ? '+' : ''}${n(f.change)} this week)`] : []),
  '',
  '*By network*',
  ...(o.byNetwork || []).map((x) => `${name(x.network)}: ${network(x)}`),
  '',
  '*Top posts*',
  ...(o.topPosts || []).slice(0, 3).map((p, i) =>
    `${i + 1}. ${(p.caption || 'Untitled').split('\n')[0].slice(0, 80)} (${name(p.network)}, ${n(p.views)} views)${p.url ? ' ' + p.url : ''}`),
];
return { json: { text: lines.join('\n') } };
